import React from 'react';
import { Chart as ChartJS, ArcElement, Tooltip, Legend } from 'chart.js';
import { Doughnut } from 'react-chartjs-2';
import {
  ShieldCheck,
  AlertTriangle,
  Cpu,
  Wrench,
  Sparkles,
  Activity,
  Zap,
  Thermometer,
  Layers,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';

ChartJS.register(ArcElement, Tooltip, Legend);

const CriticalityChart = ({ high = 11, medium = 6, low = 3 }) => {
  const navigate = useNavigate();

  const total = high + medium + low || 1;
  const highPct = Math.round((high / total) * 100);
  const mediumPct = Math.round((medium / total) * 100);
  const lowPct = Math.round((low / total) * 100);

  const data = {
    labels: [`High Risk (${high} / ${highPct}%)`, `Medium Risk (${medium} / ${mediumPct}%)`, `Low Risk (${low} / ${lowPct}%)`],
    datasets: [
      {
        data: [high, medium, low],
        backgroundColor: ['#8B5CF6', '#F59E0B', '#38BDF8'],
        borderColor: ['#ffffff', '#ffffff', '#ffffff'],
        borderWidth: 3,
        hoverOffset: 10,
      },
    ],
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'bottom',
        labels: {
          color: 'var(--text-primary)',
          font: { family: 'Plus Jakarta Sans', size: 12, weight: '800' },
          usePointStyle: true,
          boxWidth: 8,
          padding: 12,
        },
      },
      tooltip: {
        backgroundColor: '#0F172A',
        titleColor: '#FFFFFF',
        bodyColor: '#E2E8F0',
        borderColor: '#E2E8F0',
        borderWidth: 1,
        padding: 10,
      },
    },
    cutout: '62%',
  };

  // Criticality Tier Detailed Metadata
  const tierDetails = [
    {
      tier: 'High',
      color: '#8B5CF6',
      bgColor: 'var(--status-critical-bg)',
      borderColor: 'rgba(139, 92, 246, 0.3)',
      count: high,
      percentage: highPct,
      avgRul: '142 Hrs',
